#pragma warning disable CA1725
using ClosedXML.Excel;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Domain.Suppliers;
namespace WhatsBiz.Infrastructure.Suppliers;
public sealed class SupplierSpreadsheetService : ISupplierSpreadsheetService { private static readonly string[] H = ["Supplier Code", "Supplier Name", "Supplier Type", "GSTIN", "PAN", "Email", "Mobile", "Currency", "Credit Limit", "Active"]; public byte[] Export(IReadOnlyCollection<Supplier> xs) { using var w = new XLWorkbook(); var s = w.AddWorksheet("Suppliers"); Header(s); var r = 2; foreach (var x in xs) { s.Cell(r, 1).Value = x.SupplierCode; s.Cell(r, 2).Value = x.SupplierName; s.Cell(r, 3).Value = x.SupplierType; s.Cell(r, 4).Value = x.GSTIN; s.Cell(r, 5).Value = x.PAN; s.Cell(r, 6).Value = x.Email; s.Cell(r, 7).Value = x.Mobile; s.Cell(r, 8).Value = x.Currency; s.Cell(r, 9).Value = x.CreditLimit; s.Cell(r, 10).Value = x.IsActive; r++; } return Save(w); } public byte[] Template() { using var w = new XLWorkbook(); var s = w.AddWorksheet("Suppliers"); Header(s); s.Cell(2, 1).Value = "SUP-001"; s.Cell(2, 2).Value = "Sample Supplier"; s.Cell(2, 3).Value = "Domestic"; s.Cell(2, 8).Value = "INR"; s.Cell(2, 10).Value = true; return Save(w); } public IReadOnlyCollection<SupplierImportRow> Read(byte[] data) { using var m = new MemoryStream(data); using var w = new XLWorkbook(m); return w.Worksheet(1).RowsUsed().Skip(1).Where(r => !r.Cell(1).IsEmpty()).Select(r => new SupplierImportRow(r.RowNumber(), r.Cell(1).GetString(), r.Cell(2).GetString(), r.Cell(3).GetString(), N(r.Cell(4).GetString()), N(r.Cell(5).GetString()), N(r.Cell(6).GetString()), N(r.Cell(7).GetString()), r.Cell(8).GetString(), r.Cell(9).TryGetValue<decimal>(out var v) ? v : 0, !r.Cell(10).IsEmpty() && r.Cell(10).GetBoolean())).ToArray(); } private static void Header(IXLWorksheet s) { for (var i = 0; i < H.Length; i++) { s.Cell(1, i + 1).Value = H[i]; s.Cell(1, i + 1).Style.Font.Bold = true; } s.SheetView.FreezeRows(1); } private static byte[] Save(XLWorkbook w) { using var m = new MemoryStream(); w.SaveAs(m); return m.ToArray(); } private static string? N(string x) => string.IsNullOrWhiteSpace(x) ? null : x.Trim(); }
